import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { pedidosAPI } from '../services/api';
import { Trash2, Edit2 } from 'lucide-react';

const PedidoList: React.FC = () => {
  const [pedidos, setPedidos] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchPedidos = async () => {
      try {
        setLoading(true);
        const response = await pedidosAPI.listar();
        setPedidos(response.data);
      } catch (err) {
        setError('Erro ao carregar pedidos');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchPedidos();
  }, []);

  const handleDelete = async (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este pedido?')) {
      try {
        await pedidosAPI.deletar(id);
        setPedidos(pedidos.filter(pedido => pedido.idPed !== id));
      } catch (err) {
        setError('Erro ao excluir pedido');
        console.error(err);
      }
    }
  };

  if (loading) return <div className="text-center py-10">Carregando...</div>;
  if (error) return <div className="text-center text-red-500 py-10">{error}</div>;

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-800">Pedidos</h1>
        <Link to="/pedidos/novo" className="bg-indigo-600 text-white px-4 py-2 rounded-md hover:bg-indigo-700 transition-colors">
          Novo Pedido
        </Link>
      </div>

      {pedidos.length === 0 ? (
        <div className="text-center py-10 text-gray-500">
          Nenhum pedido cadastrado.
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Cliente</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Restaurante</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Data</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Valor Total</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Ações</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {pedidos.map((pedido) => (
                <tr key={pedido.idPed} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{pedido.idClientePed}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{pedido.idRestaurantePed}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{pedido.datPed}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">R$ {parseFloat(pedido.valTotalPed).toFixed(2)}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    <span className={`
                      ${pedido.dscStatusPed === 'preparando' ? 'bg-yellow-100 text-yellow-800' :
                        pedido.dscStatusPed === 'a caminho' ? 'bg-blue-100 text-blue-800' :
                        pedido.dscStatusPed === 'entregue' ? 'bg-green-100 text-green-800' :
                        'bg-gray-100 text-gray-800'}
                      px-2 py-1 rounded-full text-xs
                    `}>
                      {pedido.dscStatusPed}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 flex space-x-2">
                    <Link to={`/pedidos/${pedido.idPed}/editar`} className="text-indigo-600 hover:text-indigo-900">
                      <Edit2 className="h-4 w-4" />
                    </Link>
                    <button onClick={() => handleDelete(pedido.idPed)} className="text-red-600 hover:text-red-900">
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default PedidoList;
